#include <cstdio>
#include <cstdlib>
#define MIN(X, Y) (((X) < (Y)) ? (X) : (Y))
#define MAX(X, Y) (((X) > (Y)) ? (X) : (Y))
typedef long long l;

l a[55], b[55], ui[55];

l ask(l v) {
    printf("? %lld\n", v + 1);
    fflush(stdout);
    l t; scanf("%lld", &t);
    return t;
}

void noans() {
    printf("! -1\n");
    fflush(stdout);
}

void ans(l a, l b) {
    printf("! %lld %lld\n", a, b);
    fflush(stdout);
}

void solve() {
    l n, k; scanf("%lld %lld", &n, &k);

    for (l i = 0; i < k; ++i) a[i] = ask(i);
    for (l i = n - k; i < n; ++i) b[i % k] = ask(i);

    l uc = 0;
    for (l i = 0; i < k; ++i) if (a[i] != b[i]) ui[uc++] = i;

    if (!uc) {
        if (n == k * 2) ans(k, k);
        else noans();
        return;
    }

    l le = ui[0], ri = ui[0] + (n - 1) / k * k;
    while (le + k != ri) {
        l mid = le + (ri - le) / k / 2 * k;
        if (ask(mid) == a[ui[0]]) le = mid;
        else ri = mid;
    }

    l lee = 0, rii = uc;
    while (lee + 1 != rii) {
        l mid = (lee + rii) / 2;
        if (ask(le - ui[0] + ui[mid]) == a[ui[mid]]) lee = mid;
        else rii = mid;
    }

    l pos1 = MAX(le - ui[0] + ui[lee], k - 1);
    l pos2 = MIN(le - ui[0] + ((rii == uc) ? (ui[0] + k) : ui[rii]), n - k);

    if (pos1 + 1 != pos2) { noans(); return; }
    ans(pos2, n - pos2);
}

int main() {
    l t; scanf("%lld", &t);
    while (t--) solve();
}

#include <cstdio>
#include <vector>

#define S 200005

using namespace std;
typedef long long l;

l coloring[S], centroid, best, best_dist, n, color;
vector<vector<l>> g;

l search_centroid(l u, l from) {
  l sum = 0;
  bool f = true;
  for (l v : g[u]) if (v != from) {
    l t = search_centroid(v, u);
    if (t > n / 2) f = false;
    sum += t;
  }

  if (f && n - 1 - sum <= n / 2) centroid = u;
  return sum + 1;
}

void make_coloring(l u, l from, l dist) {
  coloring[u] = (color++) % (n / 2) + 1;
  if (g[u].size() == 1 && dist < best_dist) {
    best_dist = dist;
    best = u;
  }
  for (l v : g[u]) if (v != from)
    make_coloring(v, u, dist + 1);
}

void solve() {
  centroid = -1, best_dist = S, color = 0;
  scanf("%lld", &n);
  g.assign(n, vector<l>());
  for (l i = 0; i < n - 1; ++i) {
    l u, v; scanf("%lld %lld", &u, &v); --u, --v;
    g[u].push_back(v); g[v].push_back(u);
  }

  search_centroid(1543 % n, -1);
  make_coloring(centroid, -1, 0);

  l bbest = max(best, g[best][0]);
  coloring[centroid] = coloring[bbest];
  coloring[bbest] = 0;

  printf("%lld %lld\n", best + 1, g[best][0] + 1);
  for (l i = 0; i < n; ++i) {
    if (i) printf(" ");
    printf("%lld", coloring[i]);
  }
  printf("\n");
}

int main() {
  l tc; scanf("%lld", &tc);
  while (tc--) solve();
}

#include <cstdio>
#include <algorithm>
#include <cstring>

#define S 100005

typedef long long l;

l a[S], d[S], n;

bool check(l ans) {
    memset(d, 0, sizeof(l) * n);
    l acc = 0;

    for (l i = 0; i < n; ++i) {
        acc -= d[i];

        l need = std::max(0LL, i - (n - ans));
        if (acc < need) return false;

        l end = i + a[i] + (acc++) - need + 1;
        if (end < n) ++d[end];
    }

    return true;
}

void solve() {
    scanf("%lld", &n);
    for (l i = 0; i < n; ++i) scanf("%lld", &a[i]);

    l le = 1, ri = n + 1, mid;
    while (ri - le > 1) {
        mid = (le + ri) / 2;
        if (check(mid)) le = mid;
        else ri = mid;
    }

    printf("%lld\n", le);
}

int main() {
    l tc; scanf("%lld", &tc);
    while (tc--) solve();
}
